const body = $json.body ?? $json;
const symbol = body?.symbol;
const timeframe = body?.timeframe;
const mode = body?.mode;
const pairOk = typeof symbol === 'string' && /^[A-Z0-9]+\/[A-Z0-9]+$/.test(symbol);
const timeframeOk = typeof timeframe === 'string' && /^\d+[mhdw]$/.test(timeframe);
if (!pairOk || !timeframeOk || mode !== 'DRY_RUN') {
  return [{ json: { ok: false, statusCode: 400, error: { code: 'INVALID_INPUT', message: 'symbol and timeframe are required; mode must be DRY_RUN.' } } }];
}
return [{ json: { ok: true, symbol, timeframe, mode: 'DRY_RUN' } }];

try {
  const source = $json;
  const payload = source?.body ?? source;
  let rows = [];
  if (Array.isArray(payload?.data) && Array.isArray(payload?.columns)) {
    rows = payload.data.map((values) => Object.fromEntries(payload.columns.map((key, i) => [key, values[i] ?? null])));
  } else if (Array.isArray(payload?.candles)) {
    rows = payload.candles;
  } else if (Array.isArray(payload)) {
    rows = payload;
  }
  const fields = ['date','open','high','low','close','volume','rsi','adx','mfi','macd','macdsignal','macdhist','bb_lowerband','bb_middleband','bb_upperband','bb_percent','bb_width','sar','tema','fastd','fastk'];
  const candles = rows.map((row) => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) return null;
    const selected = {};
    for (const key of fields) if (Object.hasOwn(row, key)) selected[key] = row[key];
    return selected;
  }).filter(Boolean).slice(-30);
  if (!candles.length) return [{ json: { ok: false, statusCode: 502, error: { code: 'NO_CANDLES', message: 'Freqtrade returned no candle rows in a supported format.' } } }];
  const current = candles.at(-1);
  const n = (value) => value === null || value === undefined || value === '' ? null : Number.isFinite(Number(value)) ? Number(value) : null;
  const context = { symbol: $('Validate Input').first().json.symbol, timeframe: $('Validate Input').first().json.timeframe, mode: 'DRY_RUN', current: {
    price: n(current.close), date: current.date ?? null, volume: n(current.volume), rsi: n(current.rsi), adx: n(current.adx), mfi: n(current.mfi),
    macd: n(current.macd), macd_signal: n(current.macdsignal), macd_hist: n(current.macdhist), bb_lower: n(current.bb_lowerband),
    bb_middle: n(current.bb_middleband), bb_upper: n(current.bb_upperband), bb_percent: n(current.bb_percent), bb_width: n(current.bb_width),
    sar: n(current.sar), tema: n(current.tema), fastd: n(current.fastd), fastk: n(current.fastk), open: n(current.open), high: n(current.high), low: n(current.low)
  }, candles };
  return [{ json: { ok: true, context } }];
} catch (error) {
  return [{ json: { ok: false, statusCode: 502, error: { code: 'CANDLE_NORMALIZATION_FAILED', message: 'Could not normalize Freqtrade candle response.' } } }];
}

