try {
  const response = $json.body ?? $json;
  const raw = response?.choices?.[0]?.message?.content;
  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const validDecision = ['BUY','SELL','HOLD'].includes(parsed?.decision);
  const validConfidence = typeof parsed?.confidence === 'number' && Number.isFinite(parsed.confidence) && parsed.confidence >= 0 && parsed.confidence <= 1;
  const nullableFinite = (value) => value === null || (typeof value === 'number' && Number.isFinite(value));
  const valid = parsed && Object.keys(parsed).sort().join(',') === 'confidence,decision,entry,reason,stop_loss,take_profit'
    && validDecision && validConfidence && nullableFinite(parsed.entry) && nullableFinite(parsed.stop_loss)
    && nullableFinite(parsed.take_profit) && typeof parsed.reason === 'string' && parsed.reason.trim().length > 0;
  if (!valid) return [{ json: { ok: false, statusCode: 502, error: { code: 'INVALID_AI_RESPONSE', message: 'AI response did not satisfy the decision schema.' } } }];
  return [{ json: { ok: true, statusCode: 200, response: { decision: parsed.decision, confidence: parsed.confidence, entry: parsed.entry, stop_loss: parsed.stop_loss, take_profit: parsed.take_profit, reason: parsed.reason } } }];
} catch (error) {
  return [{ json: { ok: false, statusCode: 502, error: { code: 'INVALID_AI_RESPONSE', message: 'AI returned invalid JSON or an invalid decision.' } } }];
}
